def median(values):
    values = sorted(values)
    mid = len(values) // 2
    if len(values) % 2:
        return values[mid]
    return values[mid] / 2

import unittest
from calc import median

class MedianTests(unittest.TestCase):
    def test_odd(self):
        self.assertEqual(median([3, 1, 2]), 2)
    def test_even(self):
        self.assertEqual(median([10, 2, 4, 6]), 5)

if __name__ == '__main__':
    unittest.main()
